CREATE DATABASE IF NOT EXISTS surprise_lover CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE surprise_lover;
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_content (id INT PRIMARY KEY DEFAULT 1, owner_name VARCHAR(100) NOT NULL DEFAULT 'Your Name', partner_name VARCHAR(100) NOT NULL DEFAULT 'My Love', headline VARCHAR(255) NOT NULL DEFAULT 'You make my world brighter', love_letter TEXT NOT NULL, special_date DATE NULL, secret_message TEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT IGNORE INTO site_content (id, owner_name, partner_name, headline, love_letter, secret_message) VALUES (1,'Your Name','My Love','You make my world brighter','My love, every memory with you is precious. I made this little corner of the internet to remind you how special you are to me. Whenever you are ready, I would love to talk, listen, and understand each other with kindness.','You are special to me. When you feel ready, let us talk with open hearts. No pressure—just honesty, care, and respect.');
CREATE TABLE IF NOT EXISTS memories (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, caption VARCHAR(500) DEFAULT '', image_url VARCHAR(500) NOT NULL, memory_date DATE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS timeline (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, event_date DATE NULL, icon VARCHAR(20) DEFAULT '♥', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
